#include "sdk.h"
#include "sprite_mesh.h"
#include <SDL3/SDL.h>
#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static uint64_t hash_bytes(uint64_t h,const void*p,size_t n){const uint8_t*b=p;for(size_t i=0;i<n;i++){h^=b[i];h*=1099511628211ull;}return h;}
static bool box(const R2dJson*v,R2DSpriteMeshRect*r){const R2dJson*b=r2d_json_get(v,"frame");if(!b)b=v;double x=r2d_json_num(r2d_json_get(b,"x"),NAN),y=r2d_json_num(r2d_json_get(b,"y"),NAN),w=r2d_json_num(r2d_json_get(b,"w"),NAN),h=r2d_json_num(r2d_json_get(b,"h"),NAN);if(!isfinite(x)||!isfinite(y)||!isfinite(w)||!isfinite(h)||x<0||y<0||w<1||h<1||x>INT32_MAX||y>INT32_MAX||w>INT32_MAX||h>INT32_MAX)return false;*r=(R2DSpriteMeshRect){(int)x,(int)y,(int)w,(int)h};return x==r->x&&y==r->y&&w==r->w&&h==r->h;}
static bool number_arg(const SdkArgs*a,const char*name,double fallback,double*out){const char*s=sdk_arg_value(a,name);if(!s){*out=fallback;return true;}char*end=NULL;double x=strtod(s,&end);if(end==s||*end||!isfinite(x))return false;*out=x;return true;}
static int report(const char*code,const char*asset,const char*message){SdkReport r;sdk_report_init(&r);sdk_diag(&r,SDK_ERROR,code,asset,NULL,NULL,"%s",message);R2dSb out;r2d_sb_init(&out);r2d_sb_puts(&out,"{\"ok\":false,");sdk_report_put_counts(&r,&out);r2d_sb_putc(&out,',');sdk_report_put(&r,&out);r2d_sb_putc(&out,'}');puts(out.data);r2d_sb_free(&out);sdk_report_free(&r);return 1;}

int sdk_cmd_sprite_mesh_bake(const SdkArgs*a)
{
    const char*asset=sdk_arg_positional(a,0);if(!asset)return report("SDK_USAGE",NULL,"Использование: r2d-sdk sprite-mesh-bake <sprite.png|sprite.atlas.json> [--depth N --alpha-threshold N --units-per-pixel N --pivot-x N --pivot-y N --out cache]");
    double depth,threshold,upp,px,py;if(!number_arg(a,"--depth",0.08,&depth)||!number_arg(a,"--alpha-threshold",16,&threshold)||!number_arg(a,"--units-per-pixel",1.0/32.0,&upp)||!number_arg(a,"--pivot-x",0,&px)||!number_arg(a,"--pivot-y",0,&py)||depth<0||depth>1||threshold<0||threshold>255||floor(threshold)!=threshold||upp<=0)return report("SDK_SPRITEMESH_SETTINGS",asset,"Параметры SpriteMesh вне диапазона");
    char atlas_path[2048],image_path[2048],cache_path[2048];const bool is_atlas=sdk_ends_with(asset,".atlas.json");
    R2dJson*root=NULL;R2DSpriteMeshFrameInput*inputs=NULL;uint32_t count=1;
    if(is_atlas){SdkReport parse_rep;sdk_report_init(&parse_rep);root=sdk_load_json(asset,&parse_rep);sdk_report_free(&parse_rep);if(!root)return report("SDK_SPRITEMESH_ATLAS",asset,"Не удалось прочитать JSON атласа");const R2dJson*list=r2d_json_get(root,"frames");if(!list||(list->type!=R2D_JSON_OBJ&&list->type!=R2D_JSON_ARR)||list->count<1||list->count>65535){r2d_json_free(root);return report("SDK_SPRITEMESH_FRAMES",asset,"Атлас должен содержать 1..65535 кадров");}count=(uint32_t)list->count;inputs=calloc(count,sizeof *inputs);if(!inputs){r2d_json_free(root);return report("SDK_OUT_OF_MEMORY",asset,"Недостаточно памяти для списка кадров");}for(uint32_t i=0;i<count;i++){const R2dJson*f=list->items[i];if(!box(f,&inputs[i].rect)){free(inputs);r2d_json_free(root);return report("SDK_SPRITEMESH_FRAME",asset,"Кадр атласа имеет неверный прямоугольник");}const R2dJson*page=r2d_json_get(f,"page");if(page&&(page->type==R2D_JSON_NUM? page->number!=0 : (page->type==R2D_JSON_STR&&page->string[0]))) {free(inputs);r2d_json_free(root);return report("SDK_SPRITEMESH_PAGE",asset,"SpriteMesh bake пока принимает одну страницу текстуры");}inputs[i].pivot_x=px;inputs[i].pivot_y=py;}const char*image=r2d_json_str(r2d_json_get(r2d_json_get(root,"meta"),"image"),NULL);if(!image)image=r2d_json_str(r2d_json_get(root,"image"),NULL);if(!image){free(inputs);r2d_json_free(root);return report("SDK_SPRITEMESH_IMAGE",asset,"В атласе не задан meta.image");}sdk_dirname(asset,atlas_path,sizeof atlas_path);sdk_join(atlas_path,image,image_path,sizeof image_path);
    }else{snprintf(image_path,sizeof image_path,"%s",asset);inputs=calloc(1,sizeof *inputs);if(!inputs)return report("SDK_OUT_OF_MEMORY",asset,"Недостаточно памяти");}
    int tw=0,th=0;uint8_t*rgba=sdk_image_load_rgba(image_path,&tw,&th);if(!rgba){free(inputs);if(root)r2d_json_free(root);return report("SDK_SPRITEMESH_SOURCE",asset,"Не удалось загрузить исходную PNG текстуру");}
    if(!is_atlas){inputs[0].rect=(R2DSpriteMeshRect){0,0,tw,th};inputs[0].pivot_x=px==0?tw*.5f:px;inputs[0].pivot_y=py==0?th*.5f:py;}
    R2DSpriteMeshDesc d={(float)depth,(float)upp,0,0,(uint8_t)threshold};uint64_t source=hash_bytes(1469598103934665603ull,rgba,(size_t)tw*th*4u),layout=1469598103934665603ull;
    for(uint32_t i=0;i<count;i++){layout=hash_bytes(layout,&inputs[i].rect.x,sizeof inputs[i].rect.x);layout=hash_bytes(layout,&inputs[i].rect.y,sizeof inputs[i].rect.y);layout=hash_bytes(layout,&inputs[i].rect.w,sizeof inputs[i].rect.w);layout=hash_bytes(layout,&inputs[i].rect.h,sizeof inputs[i].rect.h);layout=hash_bytes(layout,&inputs[i].pivot_x,sizeof inputs[i].pivot_x);layout=hash_bytes(layout,&inputs[i].pivot_y,sizeof inputs[i].pivot_y);}uint64_t settings=1469598103934665603ull;settings=hash_bytes(settings,&d.depth,sizeof d.depth);settings=hash_bytes(settings,&d.units_per_pixel,sizeof d.units_per_pixel);settings=hash_bytes(settings,&d.pivot_x,sizeof d.pivot_x);settings=hash_bytes(settings,&d.pivot_y,sizeof d.pivot_y);settings=hash_bytes(settings,&d.alpha_threshold,sizeof d.alpha_threshold);
    R2DSpriteMeshCache cache={0};bool ok=r2d_sprite_mesh_build_all(rgba,tw,th,inputs,count,&d,source,layout,settings,&cache);sdk_image_free(rgba);free(inputs);if(root)r2d_json_free(root);if(!ok)return report("SDK_SPRITEMESH_BUILD",asset,"Генерация меша одного из кадров завершилась ошибкой");
    uint8_t*bytes=NULL;size_t size=0;if(!r2d_sprite_mesh_cache_encode(&cache,&bytes,&size)){r2d_sprite_mesh_cache_destroy(&cache);return report("SDK_SPRITEMESH_CACHE",asset,"Не удалось сериализовать cache");}
    const char*out=sdk_arg_value(a,"--out");if(out)snprintf(cache_path,sizeof cache_path,"%s",out);else snprintf(cache_path,sizeof cache_path,"%s.sprite-mesh.cache",asset);
    char tmp[2100];snprintf(tmp,sizeof tmp,"%s.tmp",cache_path);ok=sdk_write_file(tmp,bytes,size)&&SDL_RenamePath(tmp,cache_path);free(bytes);if(!ok){SDL_RemovePath(tmp);r2d_sprite_mesh_cache_destroy(&cache);return report("SDK_SPRITEMESH_WRITE",cache_path,"Не удалось записать cache файла");}
    uint64_t verts=0,opaque=0;for(uint32_t i=0;i<count;i++){verts+=cache.frames[i].vertex_count;opaque+=cache.frames[i].opaque_pixels;}
    R2dSb response;r2d_sb_init(&response);r2d_sb_puts(&response,"{\"ok\":true,\"asset\":");r2d_sb_put_json_string(&response,asset);r2d_sb_puts(&response,",\"cache\":");r2d_sb_put_json_string(&response,cache_path);r2d_sb_printf(&response,",\"frames\":%u,\"opaquePixels\":%llu,\"vertices\":%llu,\"triangles\":%llu,\"bytes\":%zu,\"sourceHash\":%llu,\"layoutHash\":%llu,\"settingsHash\":%llu,\"diagnostics\":[]}",count,(unsigned long long)opaque,(unsigned long long)verts,(unsigned long long)(verts/3u),size,(unsigned long long)source,(unsigned long long)layout,(unsigned long long)settings);puts(response.data);r2d_sb_free(&response);r2d_sprite_mesh_cache_destroy(&cache);return 0;
}
